#define SKIP_RUNTIME_CHECKS
#include "same-object.hpp"
#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <string>
using Clock=std::chrono::steady_clock;
std::uint64_t sink=0;
template<int Mode,bool Old,class Trie> [[gnu::noinline]] std::uint64_t query(const Trie&t,const std::vector<std::uint64_t>&q){std::uint64_t sum=0;for(auto x:q){if constexpr(Mode==0) {if constexpr(Old)sum+=t.min_xor_baseline(x).first;else sum+=t.min_xor(x).first;}else {if constexpr(Old)sum+=t.max_xor_baseline(x).first;else sum+=t.max_xor(x).first;}}return sum;}
template<int Mode,bool Old,class Trie> [[gnu::noinline]] double measure_query(const Trie&t,const std::vector<std::uint64_t>&q){auto start=Clock::now();std::uint64_t sum=0;for(int i=0;i<3;++i){sum+=query<Mode,Old>(t,q);std::atomic_signal_fence(std::memory_order_seq_cst);}auto stop=Clock::now();sink+=sum;return static_cast<double>(std::chrono::duration_cast<std::chrono::nanoseconds>(stop-start).count())/(3*q.size());}
template<bool Old,class Trie> [[gnu::noinline]] double measure_update(Trie&t,const std::vector<std::uint64_t>&q){auto start=Clock::now();for(auto x:q){if constexpr(Old){t.add_baseline(x);if(!t.del_baseline(x))std::abort();}else{t.add(x);if(!t.del(x))std::abort();}std::atomic_signal_fence(std::memory_order_seq_cst);}auto stop=Clock::now();sink+=t.size();return static_cast<double>(std::chrono::duration_cast<std::chrono::nanoseconds>(stop-start).count())/q.size();}
template<int L>int run(const std::string&shape,int n){std::mt19937_64 rng(192381);constexpr auto mask=[](){if constexpr(L==63)return UINT64_MAX;else return (std::uint64_t{1}<<(L+1))-1;}();std::vector<std::uint64_t>keys(n),queries(32768),duplicate(8192),fresh(8192);for(auto&v:keys){if(shape=="prefix")v=0x9A4C873000000000ull|(rng()&((1ull<<30)-1));else if(shape=="dense")v=rng()%65536;else v=rng()&mask;}BinaryTrie<std::uint64_t,L>b;auto& a=b;for(auto x:keys)b.add(x);for(auto&x:queries)x=rng()&mask;for(auto&x:duplicate)x=keys[rng()%keys.size()];for(auto&x:fresh){x=keys[rng()%keys.size()]^1;}
for(auto x:queries)if(a.min_xor_baseline(x).first!=b.min_xor(x).first||a.max_xor_baseline(x).first!=b.max_xor(x).first)return 2;
measure_query<0,true>(a,queries);measure_query<0,false>(b,queries);measure_update<true>(a,duplicate);measure_update<false>(b,duplicate);
for(int rep=0;rep<15;++rep){const auto emit=[&](const char*name,auto f,auto g){double x,y;if((rng()&1)!=0){x=f();y=g();}else{y=g();x=f();}std::printf("%s,%d,%s,%d,%d,%.3f,%.3f\n",name,L,shape.c_str(),n,rep,x,y);};emit("minxor",[&]{return measure_query<0,true>(a,queries);},[&]{return measure_query<0,false>(b,queries);});emit("maxxor",[&]{return measure_query<1,true>(a,queries);},[&]{return measure_query<1,false>(b,queries);});emit("duplicate_churn",[&]{return measure_update<true>(a,duplicate);},[&]{return measure_update<false>(b,duplicate);});emit("fresh_churn",[&]{return measure_update<true>(a,fresh);},[&]{return measure_update<false>(b,fresh);});}std::fprintf(stderr,"checksum=%llu\n",static_cast<unsigned long long>(sink));return 0;}
int main(int argc,char**argv){if(argc!=4)return 1;int bits=std::atoi(argv[1]);int n=std::atoi(argv[3]);return bits==30?run<29>(argv[2],n):run<63>(argv[2],n);}

