#include <vector>
#ifndef TRIE_SOURCE
#error TRIE_SOURCE is required
#endif
static std::int64_t fail_after=-1;
static std::size_t live=0;
[[gnu::noinline]] static void* obtain(std::size_t n){if(fail_after>=0&&fail_after--==0)throw std::bad_alloc();if(void*p=std::malloc(n?n:1)){++live;return p;}throw std::bad_alloc();}
void*operator new(std::size_t n){return obtain(n);}void*operator new[](std::size_t n){return obtain(n);}
[[gnu::noinline]] static void release(void*p)noexcept{if(p)--live;std::free(p);}
void operator delete(void*p)noexcept{release(p);}void operator delete[](void*p)noexcept{release(p);}void operator delete(void*p,std::size_t)noexcept{release(p);}void operator delete[](void*p,std::size_t)noexcept{release(p);}
#include TRIE_SOURCE
static std::uint64_t checks=0,failures=0;
#define REQUIRE(x)do{++checks;if(!(x)){std::cerr<<"fail line "<<__LINE__<<" "<<#x<<'\n';std::abort();}}while(false)
template<std::size_t Limit>static void nodes(){
 BinaryTrie<std::uint32_t,15,Limit>tr;
 std::set<std::pair<int,std::uint32_t>>prefixes;std::vector<std::uint32_t>keys;
 for(std::uint32_t x=0;;++x){std::size_t extra=0;for(int b=0;b<16;++b)extra+=!prefixes.contains({b,x>>b});bool fits=prefixes.size()+extra+1<=Limit;bool threw=false;try{tr.add(x);}catch(const std::length_error&){threw=true;}
 REQUIRE(threw==!fits);if(!fits){REQUIRE(!tr.contains(x));break;}for(int b=0;b<16;++b)prefixes.emplace(b,x>>b);keys.push_back(x);REQUIRE(tr.size()==keys.size());}
 for(auto x:keys)REQUIRE(tr.count(x)==1);
 if(!keys.empty()){REQUIRE(tr.min_element().first==0);REQUIRE(tr.max_element().first==keys.back());for(std::size_t k=1;k<=keys.size();k+=31)REQUIRE(tr.get_kth(k).first==keys[k-1]);}
 for(auto it=keys.rbegin();it!=keys.rend();++it)REQUIRE(tr.del(*it));REQUIRE(tr.empty());
 for(auto x:keys)REQUIRE(tr.insert_unique(65535u-x,static_cast<int>(x)));REQUIRE(tr.size()==keys.size());
 for(auto x:keys){auto f=tr.find(65535u-x);REQUIRE(f.first==1);REQUIRE(f.second.size()==1&&f.second.front()==static_cast<int>(x));}
}
static void id_expansion(){for(std::uint32_t count:{32u,4128u})for(bool existing:{false,true})for(int budget=0;budget<10;++budget){const auto before=live;{
 BinaryTrie<std::uint32_t,31,100000>tr;for(std::uint32_t x=0;x<count;++x)tr.add(x,static_cast<int>(x)+1);const std::uint32_t key=std::uint32_t{1}<<31;if(existing)tr.add(key);
 const auto size=tr.size();bool threw=false;fail_after=budget;try{tr.add(key,7000);}catch(const std::bad_alloc&){threw=true;}fail_after=-1;
 if(threw){++failures;REQUIRE(tr.size()==size);REQUIRE(tr.count(key)==static_cast<unsigned>(existing));REQUIRE(tr.find(key).second.empty());for(std::uint32_t x=0;x<count;++x){const auto f=tr.find(x);REQUIRE(f.first==1);REQUIRE(f.second.size()==1&&f.second[0]==static_cast<int>(x)+1);}tr.add(key,7000);}
 REQUIRE(tr.size()==size+1);REQUIRE(tr.count(key)==1+static_cast<unsigned>(existing));REQUIRE(tr.find(key).second.size()==1&&tr.find(key).second[0]==7000);REQUIRE(tr.del(key,7000));REQUIRE(tr.count(key)==static_cast<unsigned>(existing));if(existing)REQUIRE(tr.del(key));
 // 削除したID枠を再使用し、次の追加が元の一覧を壊さないこと。
 REQUIRE(tr.del(0,1));tr.add(0xffffffffu,9000);REQUIRE(tr.find(0xffffffffu).second.size()==1);for(std::uint32_t x=1;x<count;++x)REQUIRE(tr.find(x).second[0]==static_cast<int>(x)+1);
 }REQUIRE(live==before);}}
static void wide(){BinaryTrie<std::uint64_t,63,4096>tr;std::vector<std::uint64_t>keys{0,1,UINT64_C(0x7fffffffffffffff),UINT64_C(0x8000000000000000),UINT64_C(0x8000000000000001),UINT64_MAX};for(auto x:keys)tr.add(x,static_cast<int>(x&7));
 for(auto mask:keys){tr.operate_xor(mask);std::vector<std::uint64_t>expected;for(auto x:keys)expected.push_back(x^mask);std::sort(expected.begin(),expected.end());for(std::size_t k=1;k<=expected.size();++k)REQUIRE(tr.get_kth(k).first==expected[k-1]);for(auto x:expected)REQUIRE(tr.count(x)==1);for(auto upper:keys)REQUIRE(tr.count_less(upper)==static_cast<std::size_t>(std::lower_bound(expected.begin(),expected.end(),upper)-expected.begin()));tr.operate_xor(mask);}for(auto x:keys)REQUIRE(tr.del(x));REQUIRE(tr.empty());}
int main(){nodes<1>();nodes<16>();nodes<17>();nodes<4095>();nodes<4096>();nodes<4097>();nodes<12287>();nodes<12288>();nodes<12289>();id_expansion();wide();REQUIRE(live==0);std::cout<<"PASS checks="<<checks<<" failure_points="<<failures<<" live_delta="<<live<<'\n';}

