// SPDX-License-Identifier: CC0-1.0
#include <algorithm>
#include <atomic>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <new>
#include <set>
#include <random>
#include <type_traits>
#include <vector>
#ifndef TRIE_SOURCE
#error TRIE_SOURCE is required
#endif
static std::int64_t fail_after=-1;
static std::size_t live=0;
[[gnu::noinline]] static void* obtain(std::size_t n){if(fail_after>=0&&fail_after--==0)throw std::bad_alloc();if(void*p=std::malloc(n?n:1)){++live;return p;}throw std::bad_alloc();}
void*operator new(std::size_t n){return obtain(n);}void*operator new[](std::size_t n){return obtain(n);}
[[gnu::noinline]] static void release(void*p)noexcept{if(p)--live;std::free(p);}
void operator delete(void*p)noexcept{release(p);}void operator delete[](void*p)noexcept{release(p);}void operator delete(void*p,std::size_t)noexcept{release(p);}void operator delete[](void*p,std::size_t)noexcept{release(p);}
#include TRIE_SOURCE
static std::uint64_t checks=0, failures=0;
#define REQUIRE(x) do { ++checks; if (!(x)) { std::cerr << "failed line " << __LINE__ << ": " << #x << '\n'; std::abort(); } } while(false)
template<class T, int L, std::size_t N=20000> struct State {
 using U=std::make_unsigned_t<T>;
 using Entry=std::pair<U,int>;
 static constexpr U mask=[] { if constexpr(L+1==std::numeric_limits<U>::digits) return std::numeric_limits<U>::max(); else return static_cast<U>((U{1}<<(L+1))-1); }();
 BinaryTrie<T,L,N>tr;
 std::vector<Entry> ref;
 std::mt19937_64 rng{817239};
 void check() {
  REQUIRE(tr.size()==ref.size());REQUIRE(tr.empty()==ref.empty());
  std::vector<U> queries{U{0},U{1},mask,static_cast<U>(U{1}<<L),static_cast<U>(rng()&mask),static_cast<U>(rng()&mask)};
  if(!ref.empty()){queries.push_back(ref.front().first);queries.push_back(ref.back().first);}
  const auto expected_ids=[&](U x){std::vector<int>ids;for(auto[v,id]:ref)if(v==x&&id!=-1)ids.push_back(id);std::sort(ids.begin(),ids.end());return ids;};
  for(const U x:queries){std::size_t cnt=0;for(auto[v,id]:ref)cnt+=v==x;REQUIRE(tr.count(static_cast<T>(x))==cnt);auto f=tr.find(static_cast<T>(x));REQUIRE(f.first==cnt);auto ids=f.second;std::sort(ids.begin(),ids.end());REQUIRE(ids==expected_ids(x));
   if(!ref.empty()){U mn=mask,mx=0;for(auto[v,id]:ref){mn=std::min(mn,static_cast<U>(v^x));mx=std::max(mx,static_cast<U>(v^x));}auto a=tr.min_xor(static_cast<T>(x));auto b=tr.max_xor(static_cast<T>(x));REQUIRE(static_cast<U>(a.first)==mn);REQUIRE(static_cast<U>(b.first)==mx);auto ai=a.second,bi=b.second;std::sort(ai.begin(),ai.end());std::sort(bi.begin(),bi.end());REQUIRE(ai==expected_ids(mn^x));REQUIRE(bi==expected_ids(mx^x));}
  }
 }
 bool add(U x,int id,bool unique=false){bool inserted=true;bool threw=false;try{if(unique)inserted=tr.insert_unique(static_cast<T>(x),id);else tr.add(static_cast<T>(x),id);}catch(const std::length_error&){threw=true;}
  if(!threw){if(unique){const bool present=std::any_of(ref.begin(),ref.end(),[&](Entry e){return e.first==x;});REQUIRE(inserted==!present);}if(inserted)ref.emplace_back(x,id);}check();return !threw&&inserted;
 }
 void erase(U x,int id=-1){auto it=std::find_if(ref.begin(),ref.end(),[&](Entry e){return e.first==x&&(id==-1||e.second==id);});const bool present=it!=ref.end();REQUIRE(tr.del(static_cast<T>(x),id)==present);if(present){if(id!=-1)ref.erase(it);else{auto anon=std::find(ref.begin(),ref.end(),Entry{x,-1});if(anon!=ref.end())ref.erase(anon);else{const auto now=tr.find(static_cast<T>(x)).second;std::multiset<int>actual(now.begin(),now.end());for(auto e:ref)if(e.first==x&&e.second!=-1){auto a=actual.find(e.second);if(a==actual.end()){ref.erase(std::find(ref.begin(),ref.end(),e));break;}actual.erase(a);}}}}check();}
 void lazy(U mask){tr.operate_xor(static_cast<T>(mask));for(auto&e:ref)e.first^=mask;check();}
 void clear(){while(!ref.empty()){auto[v,id]=ref.back();erase(v,id);}check();}
};
template<class T,int L>static void transitions(){using S=State<T,L>;using U=typename S::U;S s;for(int cycle=0;cycle<3;++cycle){const U base=static_cast<U>(s.rng()&S::mask);REQUIRE(s.add(base,7));REQUIRE(!s.add(base,999,true));s.add(base,7);s.add(base,-1);s.erase(base,999);s.erase(base);s.erase(base,7);
 // 分岐の最高位を1bitずつ上げて、次に逆順で削除する。
 for(int bit=0;bit<=L;++bit)REQUIRE(s.add(static_cast<U>(base^(U{1}<<bit)),100+bit));
 s.erase(base,7); // prefix代表値の葉自体を消す。
 const U xor_mask=static_cast<U>(s.rng()&S::mask);s.lazy(xor_mask);
 for(int bit=L;bit>=0;--bit)s.erase(static_cast<U>(base^(U{1}<<bit)^xor_mask),100+bit);
 REQUIRE(s.tr.empty());s.add(static_cast<U>(base^xor_mask),19);s.lazy(S::mask);s.add(static_cast<U>(base^xor_mask^S::mask),-1);s.clear();}}
template<std::size_t N>static void capacity(){using S=State<std::uint64_t,63,N>;S s;constexpr std::uint64_t base=UINT64_C(0xa5f0000000000034);REQUIRE(s.add(base,1));for(auto delta:{UINT64_C(1),UINT64_C(0x8000000000000000),UINT64_C(2),UINT64_C(0x4000000000000000)}){s.add(base^delta,3);s.add(base^delta,4,true);}s.erase(base,999);s.clear();REQUIRE(s.add(~base,6));s.clear();}
static void allocations(){using S=State<std::uint64_t,63,100000>;for(int scenario=0;scenario<5;++scenario)for(int budget=0;budget<10;++budget){const auto before=live;{S s;constexpr std::uint64_t base=UINT64_C(0xa5f0000000000000);const unsigned count=scenario==4?4128u:scenario==0?0u:32u;
 for(unsigned i=0;i<count;++i){s.tr.add(base|i,static_cast<int>(i)+10);s.ref.emplace_back(base|i,static_cast<int>(i)+10);}std::uint64_t target=base^(UINT64_C(1)<<63);if(scenario==2)target=base|512;if(scenario==3){target=base|1024;s.tr.add(target);s.ref.emplace_back(target,-1);}s.check();const auto old=s.ref;bool threw=false;
 fail_after=budget;try{s.tr.add(target,9000);}catch(const std::bad_alloc&){threw=true;}fail_after=-1;
 if(threw){++failures;REQUIRE(s.ref==old);s.check();s.tr.add(target,9000);}s.ref.emplace_back(target,9000);s.check();s.erase(target,9000);s.check();
 }REQUIRE(live==before);}}
int main(){transitions<unsigned,0>();transitions<unsigned char,7>();transitions<std::uint32_t,31>();transitions<std::int64_t,62>();transitions<std::uint64_t,63>();capacity<65>();capacity<66>();capacity<67>();capacity<100>();capacity<129>();capacity<130>();allocations();REQUIRE(live==0);std::cout<<"PASS prefix_transitions checks="<<checks<<" failures="<<failures<<" live_delta="<<live<<'\n';}
